import{_ as t,o as a,c as o,a2 as s}from"./chunks/framework.Dnb1kVW5.js";const u=JSON.parse('{"title":"Install Orby","description":"","frontmatter":{"title":"Install Orby"},"headers":[],"relativePath":"docs/getting-started/install-orby.md","filePath":"docs/getting-started/install-orby.md","lastUpdated":1789167487000}'),r={name:"docs/getting-started/install-orby.md"};function n(d,e,l,i,h,c){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="install-orby" tabindex="-1">Install Orby <a class="header-anchor" href="#install-orby" aria-label="Permalink to &quot;Install Orby&quot;">​</a></h1><p>Orby is a desktop app for macOS, Windows, and Linux. Head to the <a href="/orby-releases/">Downloads</a> page — it detects your operating system and recommends the right build automatically.</p><table tabindex="0"><thead><tr><th>Platform</th><th>Formats</th></tr></thead><tbody><tr><td>macOS</td><td><code>.dmg</code>, <code>.zip</code></td></tr><tr><td>Windows</td><td>installer (<code>.exe</code>) or portable <code>.exe</code></td></tr><tr><td>Linux</td><td><code>.AppImage</code> or <code>.deb</code></td></tr></tbody></table><p>Download the recommended asset (or pick a different one from the platform cards) and install it the way you normally would for your OS.</p><blockquote><p><strong>Orby is currently in Alpha.</strong> It&#39;s free to use, but expect bugs and unfinished features. See the notice on the Downloads page for the latest status.</p></blockquote><h2 id="what-happens-on-first-launch" tabindex="-1">What happens on first launch <a class="header-anchor" href="#what-happens-on-first-launch" aria-label="Permalink to &quot;What happens on first launch&quot;">​</a></h2><p>There&#39;s no separate setup wizard. When you open Orby with no projects yet, an onboarding checklist appears in the corner of the window with three steps:</p><ol><li>Create a project</li><li>Add a source</li><li>Ask a question</li></ol><p>Each step checks itself off automatically as you complete it, and the checklist dismisses itself once all three are done. The rest of this section walks through exactly those three steps.</p><p>The very first launch may take a little while to get ready — Orby sets up its initial environment and, if you&#39;re using a local model, downloads it in the background. After that, startup is fast.</p><h2 id="choosing-a-model" tabindex="-1">Choosing a model <a class="header-anchor" href="#choosing-a-model" aria-label="Permalink to &quot;Choosing a model&quot;">​</a></h2><p>Orby supports a few different size local models, and will download one on demand based on your hardware - this may take a little while, depending on which model is chosen and your internet speed. You can also specify to use a model at a standard OpenAI API endpoint - this is configured in <strong>Settings</strong>. See <a href="/orby-releases/docs/settings/models">Models</a> for details.</p>',12)])])}const f=t(r,[["render",n]]);export{u as __pageData,f as default};
